'use strict';

const cache = new Map();

module.exports = async function cached(key, load) {
  if (!cache.has(key)) cache.set(key, await load());
  return cache.get(key);
};

'use strict';

const target = require('../index');

test('caches results', () => {
  return target('k', async () => 1).then((v) => expect(v).toBe(1));
});

